import type { FormProps, BaseFormProps } from "./form.types";

import { clsx } from "clsx";
import { useTheme } from "@theme";
import { FormProvider, useForm, type FieldValues, type UseFormReturn } from "react-hook-form";

import { FormClasses, StyledForm } from "./form.styles";
import { FormContext } from "./hooks/use-form-size";

type FormLayoutProps<T extends FieldValues> = BaseFormProps<T> & {
  methods: UseFormReturn<T>;
};

const FormLayout = <T extends FieldValues>({
  className,
  children,
  onSubmit,
  formSize = "default",
  methods,
  ...props
}: FormLayoutProps<T>) => {
  const theme = useTheme();
  const rootClasses = clsx(FormClasses.root, className, {
    [FormClasses.sm]: formSize === "sm",
  });

  return (
    <FormProvider {...methods}>
      <FormContext.Provider value={{ formSize }}>
        <StyledForm
          noValidate
          className={rootClasses}
          currentTheme={theme}
          {...props}
          onSubmit={onSubmit ? methods.handleSubmit(onSubmit) : undefined}
        >
          {typeof children === "function" ? children(methods) : children}
        </StyledForm>
      </FormContext.Provider>
    </FormProvider>
  );
};

const Form = <T extends FieldValues>(props: FormProps<T>) => {
  if (props.methods) {
    return <FormLayout {...props} methods={props.methods} />;
  }

  // eslint-disable-next-line react-hooks/rules-of-hooks
  const methods = useForm<T>(props.options);
  return <FormLayout {...props} methods={methods} />;
};

Form.displayName = "Form";

export default Form;
